    /// Typed value enum — payload-eligible branches carry typed
    /// values directly; non-eligible branches wrap a cursor view.
    #[derive(Clone, Debug)]
    pub enum mathValueValue<'p> {
        calcFunction(CssL4ParserNodeView<'p>),
        minFunction(CssL4ParserNodeView<'p>),
        maxFunction(CssL4ParserNodeView<'p>),
        clampFunction(CssL4ParserNodeView<'p>),
        valueUnit(CssL4ParserNodeView<'p>),
        number(f64),
        branch_6(CssL4ParserNodeView<'p>),
        varFunction(CssL4ParserNodeView<'p>),
        envFunction(CssL4ParserNodeView<'p>),
    }
    impl<'p> mathValueView<'p> {
        /// Decode the chosen branch's value. Payload-eligible
        /// branches return typed scalars/aggregates; other
        /// branches return cursor-wrapped sub-views.
        #[inline]
        pub fn value(&self) -> ::core::option::Option<mathValueValue<'p>> {
            match self.cursor.meta_idx() {
                0u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::calcFunction(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                1u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::minFunction(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                2u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::maxFunction(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                3u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::clampFunction(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                4u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::valueUnit(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                5u8 => {
                    let __cursor = self.cursor.child(0).unwrap_or(self.cursor);
                    let __rec = __cursor.record();
                    let __tape = __cursor.tape();
                    let __value = __tape
                        .payload_f64(__rec)
                        .unwrap_or(<f64 as ::core::default::Default>::default());
                    Some(mathValueValue::number(__value))
                }
                6u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::branch_6(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                7u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::varFunction(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                8u8 => {
                    let __child = self.cursor.child(0)?;
                    Some(
                        mathValueValue::envFunction(
                            CssL4ParserNodeView::from_cursor(__child, self.input),
                        ),
                    )
                }
                _ => None,
            }
        }
    }
