        /// Iterator over direct children as `NodeView`s.
        #[inline]
        pub fn children(
            &self,
        ) -> impl ::core::iter::Iterator<Item = CssL4ParserNodeView<'p>> + 'p {
            let input = self.input;
            self.cursor
                .children()
                .map(move |c| CssL4ParserNodeView::from_cursor(c, input))
        }
        /// The i-th direct child as a `NodeView`, if present.
        #[inline]
        pub fn child(
            &self,
            i: usize,
        ) -> ::core::option::Option<CssL4ParserNodeView<'p>> {
            self.cursor.child(i).map(|c| CssL4ParserNodeView::from_cursor(c, self.input))
        }
        #[inline]
        pub fn is_recovered(&self) -> bool {
            self.cursor.kind().is_recovered()
        }
