        pub fn new(
            tape: &'p crate::runtime::tape::Tape,
            input: &'p str,
            offset: crate::runtime::tape::TapeOffset,
        ) -> Self {
            Self {
                cursor: crate::runtime::tape::TapeCursor::new(tape, offset),
                input,
            }
        }
        #[inline]
